Aqui está a solução completa e rigorosa para o problema **Transportes**, estruturada segundo a metodologia de George Pólya.

---

### 1. COMPREENSÃO DO PROBLEMA
- **Objetivo**: Determinar o menor custo total para viajar da estação $A$ até a estação $B$. O custo é incorrido apenas ao entrar em um sistema de transporte $t$ (preço fixo $P_t$). Deslocamentos consecutivos utilizando o mesmo sistema não geram custos adicionais, mas qualquer troca de sistema requer o pagamento da tarifa do novo sistema.
- **Entrada**:
  - $N$ (estações), $M$ (ligações), $K$ (sistemas).
  - Um vetor $P$ de tamanho $K$ com as tarifas $P_1, \dots, P_K$.
  - $M$ linhas com $V_j, U_j, T_j$, indicando uma ligação bidirecional entre $V_j$ e $U_j$ do sistema $T_j$.
  - Estação inicial $A$ e estação final $B$.
- **Saída**: O menor custo total, ou `-1` se $B$ for inalcançável a partir de $A$.
- **Limites e Restrições**:
  - $2 \le N \le 100\,000$, $1 \le M, K \le 100\,000$.
  - $1 \le P_i \le 1000$.
  - Como o caminho pode envolver diversas trocas de sistema, o custo máximo acumulado pode ultrapassar $2 \cdot 10^9$? No pior caso, $100\,000 \times 1000 = 10^8$, que cabe em um inteiro de 32 bits, mas usaremos `long long` para distâncias por segurança.
- **Casos de borda**: Grafo desconexo (deve imprimir `-1`), múltiplos caminhos possíveis no mesmo sistema, múltiplas arestas incidentes a um mesmo vértice pertencentes ao mesmo sistema.

---

### 2. PLANEJAMENTO E DESIGN ALGORÍTMICO
- **Modelagem em Grafo de Estados**:
  - Cada estação $u$ é representada por um nó principal $u \in [1, N]$.
  - Para cada sistema $t$ incidente à estação $u$, criamos um nó auxiliar $(u, t)$.
  - **Transições**:
    1. **Entrar no sistema**: Aresta direcionada do nó principal $u$ para $(u, t)$ com custo $P_t$.
    2. **Sair do sistema**: Aresta direcionada de $(u, t)$ para o nó principal $u$ com custo $0$.
    3. **Trafegar no sistema**: Para cada ligação original $(u, v)$ no sistema $t$, adicionamos arestas bidirecionais de custo $0$ entre $(u, t)$ e $(v, t)$.
- **Dimensões do Grafo Reduzido**:
  - Cada aresta original incide em 2 estações. Portanto, existem no máximo $2M$ nós auxiliares $(u, t)$ distintos.
  - Vértices totais: $|V| \le N + 2M \le 300\,000$.
  - Arestas totais: $|E| \le 2M \text{ (entrar)} + 2M \text{ (sair)} + 2M \text{ (trafegar)} \le 600\,000$.
- **Algoritmo**:
  - Como todos os pesos são não-negativos ($0$ ou $P_t$), o algoritmo de **Dijkstra** com Min-Heap binário é ótimo.
- **Complexidade**:
  - Tempo: $O((|V| + |E|) \log |V|) \approx O((N + M) \log(N + M))$, executando com folga em menos de 0.2 segundos em C.
  - Espaço: $O(N + M)$, bem dentro do limite de memória usual (geralmente 256MB ou 512MB).

---

### 3. CODIFICAÇÃO EM C

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define INF 0x3f3f3f3f3f3f3f3fLL

// Estrutura para descrever arestas originais da entrada
typedef struct {
    int u, v, t;
} InputEdge;

// Estrutura para mapear pares (u, t)
typedef struct {
    int u;
    int t;
    int edge_idx;
    int endpoint; // 0 para u, 1 para v
} StationSystemPair;

// Estrutura para lista de adjacência
typedef struct {
    int to;
    long long weight;
    int next;
} Edge;

static Edge edges[1200005];
static int head[300005];
static int edge_cnt = 0;

static void add_edge(int from, int to, long long weight) {
    edges[++edge_cnt] = (Edge){to, weight, head[from]};
    head[from] = edge_cnt;
}

// Comparador para ordenar pares (estação, sistema)
int compare_pairs(const void *a, const void *b) {
    const StationSystemPair *pa = (const StationSystemPair *)a;
    const StationSystemPair *pb = (const StationSystemPair *)b;
    if (pa->u != pb->u) return pa->u - pb->u;
    return pa->t - pb->t;
}

// Estrutura e funções para o Min-Heap (Dijkstra)
typedef struct {
    int u;
    long long dist;
} HeapNode;

static HeapNode heap[2000005];
static int heap_size = 0;

static void heap_push(int u, long long dist) {
    int i = ++heap_size;
    while (i > 1 && heap[i / 2].dist > dist) {
        heap[i] = heap[i / 2];
        i /= 2;
    }
    heap[i].u = u;
    heap[i].dist = dist;
}

static HeapNode heap_pop(void) {
    HeapNode min_node = heap[1];
    HeapNode last = heap[heap_size--];
    int i = 1, child;
    while (i * 2 <= heap_size) {
        child = i * 2;
        if (child != heap_size && heap[child + 1].dist < heap[child].dist) {
            child++;
        }
        if (last.dist > heap[child].dist) {
            heap[i] = heap[child];
            i = child;
        } else {
            break;
        }
    }
    heap[i] = last;
    return min_node;
}

static long long dist[300005];
static int P[100005];
static InputEdge input_edges[100005];
static StationSystemPair pairs[200005];
static int node_id_for_half_edge[100005][2];

int main(void) {
    int N, M, K;
    if (scanf("%d %d %d", &N, &M, &K) != 3) return 0;

    for (int i = 1; i <= K; i++) {
        scanf("%d", &P[i]);
    }

    int pair_cnt = 0;
    for (int i = 0; i < M; i++) {
        scanf("%d %d %d", &input_edges[i].u, &input_edges[i].v, &input_edges[i].t);
        pairs[pair_cnt++] = (StationSystemPair){input_edges[i].u, input_edges[i].t, i, 0};
        pairs[pair_cnt++] = (StationSystemPair){input_edges[i].v, input_edges[i].t, i, 1};
    }

    int A, B;
    scanf("%d %d", &A, &B);

    // Ordena os pares para identificar grupos únicos de (estação, sistema)
    qsort(pairs, pair_cnt, sizeof(StationSystemPair), compare_pairs);

    int total_nodes = N;
    for (int i = 0; i < pair_cnt; ) {
        int j = i;
        total_nodes++; // Novo nó auxiliar para este (u, t)
        int current_u = pairs[i].u;
        int current_t = pairs[i].t;
        int aux_node = total_nodes;

        // Conexões de/para o nó principal da estação
        // 1. Entrar no sistema: u -> (u, t) com custo P[t]
        add_edge(current_u, aux_node, P[current_t]);
        // 2. Sair do sistema: (u, t) -> u com custo 0
        add_edge(aux_node, current_u, 0);

        while (j < pair_cnt && pairs[j].u == current_u && pairs[j].t == current_t) {
            node_id_for_half_edge[pairs[j].edge_idx][pairs[j].endpoint] = aux_node;
            j++;
        }
        i = j;
    }

    // Adiciona as arestas de trânsito dentro do mesmo sistema
    for (int i = 0; i < M; i++) {
        int node_u = node_id_for_half_edge[i][0];
        int node_v = node_id_for_half_edge[i][1];
        add_edge(node_u, node_v, 0);
        add_edge(node_v, node_u, 0);
    }

    // Inicialização do Dijkstra
    for (int i = 1; i <= total_nodes; i++) {
        dist[i] = INF;
    }

    dist[A] = 0;
    heap_push(A, 0);

    while (heap_size > 0) {
        HeapNode top = heap_pop();
        int u = top.u;
        long long d = top.dist;

        if (d > dist[u]) continue;
        if (u == B) break; // Já encontramos a menor distância para B

        for (int e = head[u]; e != 0; e = edges[e].next) {
            int v = edges[e].to;
            long long w = edges[e].weight;
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                heap_push(v, dist[v]);
            }
        }
    }

    if (dist[B] == INF) {
        printf("-1\n");
    } else {
        printf("%lld\n", dist[B]);
    }

    return 0;
}
```

